:root {
  --ink: #24312d;
  --paper: #fffdf5;
  --line: #d7dfce;
  --lime: #c9ef62;
  --muted: #66736d;
}

.clue-card {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background-color: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.marker {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  background-color: var(--lime);
  font-size: 21px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.card-header h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
}

.clue {
  margin: 16px 0;
  padding: 10px 12px;
  border-left: 4px solid var(--lime);
  background-color: var(--line);
  font-size: 14px;
  line-height: 1.35;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.code {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.reveal-button {
  padding: 7px 11px;
  border: 2px solid var(--ink);
  border-radius: 7px;
  background-color: var(--lime);
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}
